{
  "ideas": [
    {
      "title": "One-button 'Heat It' with IR doneness sensor",
      "anchors": ["F8", "X5"],
      "new_nodes": [
        {"type": "Component", "label": "Single HEAT button", "detail": "One pushbutton replaces timer and power knobs; cooking stops automatically."},
        {"type": "Technology", "label": "IR thermopile surface-temperature sensing", "detail": "Non-contact sensor reads food surface temperature through a waveguide-safe window."}
