      "new_edges": [
        {"from": "Single HEAT button", "to": "F8", "type": "resolves"},
        {"from": "Single HEAT button", "to": "X5", "type": "resolves"},
        {"from": "Single HEAT button", "to": "IR thermopile surface-temperature sensing", "type": "enabled_by"},
        {"from": "Single HEAT button", "to": "M6", "type": "relevant_to"}
      ],
      "rationale": "Zero settings to understand: press once, food stops when hot."
    },
    {
      "title": "Hold-to-heat dead-man button",
      "anchors": ["F8", "X5"],
      "new_nodes": [
        {"type": "Component", "label": "Momentary hold-to-heat paddle", "detail": "Magnetron runs only while the user holds the paddle; release stops it instantly."}
