      "new_edges": [
        {"from": "Spring-loaded pop-up lever", "to": "T18", "type": "resolves"},
        {"from": "Spring-loaded pop-up lever", "to": "F8", "type": "performs_function"},
        {"from": "Spring-loaded pop-up lever", "to": "M6", "type": "relevant_to"}
